import React, { useEffect, useState } from 'react';
import api from "../api/axios";
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';

const AdminDashboard = () => {
  const token = useSelector((state) => state.auth.token);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filterStatus, setFilterStatus] = useState('All');
  const [sortOrder, setSortOrder] = useState('desc');

  useEffect(() => {
    if (!token) {
      setError('Please log in.');
      setLoading(false);
      return;
    }

    const fetchTickets = async () => {
      try {
        const response = await api.get('/tickets/', {
          headers: { Authorization: `Bearer ${token}` },
        });
        setTickets(response.data);
      } catch (err) {
        console.error('Error fetching tickets:', err);
        setError('Failed to load tickets.');
        if (err.response?.status === 401) {
          dispatch({ type: 'auth/logout' });
          navigate('/login');
        }
      } finally {
        setLoading(false);
      }
    };
    fetchTickets();
  }, [token, dispatch, navigate]);

  // Status counts for overview cards
  const statusCounts = {
    Total: tickets.length,
    Open: tickets.filter(t => t.status === 'OPEN').length,
    InProgress: tickets.filter(t => t.status === 'IN_PROGRESS').length,
    Resolved: tickets.filter(t => t.status === 'RESOLVED').length,
    PartiallyClosed: tickets.filter(t => t.status === 'PARTIALLY_CLOSED').length,
  };

  // Priority mapping
  const getPriorityValue = (priority) => {
    switch (priority?.toUpperCase()) {
      case 'HIGH': return 3;
      case 'MEDIUM': return 2;
      case 'LOW': return 1;
      default: return 0;
    }
  };

  // Filter and sort logic
  const filteredTickets = tickets.filter(ticket =>
    filterStatus === 'All' ? true : ticket.status === filterStatus
  );

  const sortedTickets = [...filteredTickets].sort((a, b) => {
    const priA = getPriorityValue(a.priority);
    const priB = getPriorityValue(b.priority);
    return sortOrder === 'asc' ? priA - priB : priB - priA;
  });

  const toggleSort = () => {
    setSortOrder(prev => (prev === 'asc' ? 'desc' : 'asc'));
  };

  const handleLogout = () => {
    dispatch({ type: 'auth/logout' });
    navigate('/login'); // or your login page route
  };

  const getPriorityColor = (priority) => {
    const p = priority?.toUpperCase() || '';
    if (p === 'HIGH') return '#ff4d4f';
    if (p === 'MEDIUM') return '#faad14';
    if (p === 'LOW') return '#52c41a';
    return '#d9d9d9';
  };

  const getStatusColor = (status) => {
    const s = status?.toUpperCase() || '';
    switch (s) {
      case 'OPEN': return '#1890ff';
      case 'IN_PROGRESS': return '#faad14';
      case 'RESOLVED': return '#52c41a';
      case 'PARTIALLY_CLOSED': return '#9254de';
      default: return '#d9d9d9';
    }
  };

  if (loading) return <div style={styles.loading}>Loading tickets...</div>;
  if (error) return <div style={styles.error}>{error}</div>;

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>Admin Dashboard - All Tickets</h1>
        <button onClick={handleLogout} style={styles.logoutButton}>
          Logout
        </button>
      </div>

      {/* Overview Cards */}
      <div style={styles.countsGrid}>
        <div style={{ ...styles.countCard, background: '#4527a0' }}>
          <div style={styles.countNumber}>{statusCounts.Total}</div>
          <p style={styles.countLabel}>Total Tickets</p>
        </div>
        <div style={{ ...styles.countCard, background: getStatusColor('OPEN') }}>
          <div style={styles.countNumber}>{statusCounts.Open}</div>
          <p style={styles.countLabel}>Open</p>
        </div>
        <div style={{ ...styles.countCard, background: getStatusColor('IN_PROGRESS') }}>
          <div style={styles.countNumber}>{statusCounts.InProgress}</div>
          <p style={styles.countLabel}>In Progress</p>
        </div>
        <div style={{ ...styles.countCard, background: getStatusColor('RESOLVED') }}>
          <div style={styles.countNumber}>{statusCounts.Resolved}</div>
          <p style={styles.countLabel}>Resolved</p>
        </div>
        <div style={{ ...styles.countCard, background: getStatusColor('PARTIALLY_CLOSED') }}>
          <div style={styles.countNumber}>{statusCounts.PartiallyClosed}</div>
          <p style={styles.countLabel}>Partially Closed</p>
        </div>
      </div>

      {/* Filter & Sort */}
      <div style={styles.controls}>
        <div>
          <label style={styles.label}>Filter by Status: </label>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            style={styles.select}
          >
            <option value="All">All</option>
            <option value="OPEN">Open</option>
            <option value="IN_PROGRESS">In Progress</option>
            <option value="RESOLVED">Resolved</option>
            <option value="PARTIALLY_CLOSED">Partially Closed</option>
          </select>
        </div>

        <button onClick={toggleSort} style={styles.sortButton}>
          Sort by Priority: {sortOrder === 'asc' ? 'Low → High' : 'High → Low'}
        </button>
      </div>

      {/* Ticket Cards Grid */}
      <div style={styles.ticketsGrid}>
        {sortedTickets.length === 0 ? (
          <p style={styles.noTickets}>No tickets found</p>
        ) : (
          sortedTickets.map((ticket) => (
            <div
              key={ticket.id}
              style={styles.ticketCard}
              onClick={() => navigate(`/tickets/${ticket.id}`)}
            >
              <div style={styles.ticketHeader}>
                <h3 style={styles.ticketTitle}>#{ticket.id} - {ticket.title}</h3>
                <span
                  style={{
                    ...styles.badge,
                    background: getPriorityColor(ticket.priority),
                  }}
                >
                  {ticket.priority || 'N/A'}
                </span>
                <span
                  style={{
                    ...styles.badge,
                    background: getStatusColor(ticket.status),
                  }}
                >
                  {ticket.status}
                </span>
              </div>
              <p style={styles.ticketMeta}>
                Creator: {ticket.creator?.email || ticket.creator?.username || 'N/A'}
              </p>
              <p style={styles.ticketDescription}>
                {ticket.description?.substring(0, 120)}{ticket.description?.length > 120 ? '...' : ''}
              </p>
              <p style={styles.ticketDate}>
                Created: {new Date(ticket.created_at).toLocaleDateString()}
              </p>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

